create table public.specialist_analyses(id uuid primary key default gen_random_uuid(),analysis_key text not null unique,contract_version text not null,specialist text not null check(specialist in('MOMENTUM','TOKEN_RISK','FUNDAMENTAL')),asset_id uuid not null references public.assets(id),opportunity_id uuid references public.opportunities(id),information_cutoff_at timestamptz not null,available_at timestamptz not null,conclusion text not null check(conclusion in('SUPPORTED','NOT_SUPPORTED','INSUFFICIENT_DATA')),data_quality numeric,limitations jsonb not null default'[]',knowledge_request_hash text not null,knowledge_rule_refs jsonb not null default'[]',evidence_refs jsonb not null default'[]',input_context jsonb not null default'{}',analysis_hash text not null,created_at timestamptz not null default now());create table public.specialist_analysis_components(id uuid primary key default gen_random_uuid(),analysis_id uuid not null references public.specialist_analyses(id),component_code text not null,status text not null check(status in('PASS','FAIL','UNKNOWN','NOT_APPLICABLE')),observed_value jsonb,required_value jsonb,evidence_refs jsonb not null default'[]',reason text not null,unique(analysis_id,component_code));
create or replace function public.prevent_specialist_analysis_mutation()returns trigger language plpgsql as $$begin raise exception'Specialist analysis history is immutable';end$$;create trigger specialist_analyses_immutable before update or delete on public.specialist_analyses for each row execute function public.prevent_specialist_analysis_mutation();create trigger specialist_components_immutable before update or delete on public.specialist_analysis_components for each row execute function public.prevent_specialist_analysis_mutation();alter table public.specialist_analyses enable row level security;alter table public.specialist_analysis_components enable row level security;create policy "public read specialist analyses" on public.specialist_analyses for select using(true);create policy "public read specialist components" on public.specialist_analysis_components for select using(true);grant select on public.specialist_analyses,public.specialist_analysis_components to anon,authenticated;grant all on public.specialist_analyses,public.specialist_analysis_components to service_role;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance','fx','qualification','data_gap_closure','simulation','historical_replay','forecast_catalyst','expert_knowledge','baseline_forecast','forecast_performance','forecast_scheduler','forecast_outcomes','specialist_agents'));
